//! Does every character the interface draws have a font that can draw it?
//!
//! Four glyphs shipped as blank squares before this existed; the render gates compare
//! fractal pixels and cannot see a menu. Test-only, but a SEPARATE FILE on purpose:
//! `icons.rs` is generated by `scripts/subset_lucide.py`, which rewrites it whole. This
//! module lived at the bottom of that file until regenerating it for one new icon deleted
//! the check silently - the tests simply stopped existing and the suite still went green.
//! Generated and hand-written code do not share a file.

use std::collections::BTreeSet;

/// The Proportional family as `theme::install_fonts` builds it. Coverage is a union, so the
/// order is documentation rather than logic.
const FONTS: &[(&str, &[u8])] = &[
    ("SplineSans", include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/fonts/SplineSans.ttf"))),
    ("SplineSansMono", include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/fonts/SplineSansMono.ttf"))),
    ("Lucide", include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/fonts/Lucide.ttf"))),
    ("Ubuntu-Light", epaint_default_fonts::UBUNTU_LIGHT),
    ("NotoEmoji", epaint_default_fonts::NOTO_EMOJI_REGULAR),
    ("emoji-icon-font", epaint_default_fonts::EMOJI_ICON),
    ("Hack", epaint_default_fonts::HACK_REGULAR),
    // The language menu's own names of Japanese and Chinese (`scripts/subset_names_font.py`).
    ("NamesJP", include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/fonts/NamesJP.otf"))),
    ("NamesSC", include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/assets/fonts/NamesSC.otf"))),
];

/// `include_str!` rather than a directory walk, so this works from any working directory and
/// fails to COMPILE if a file is renamed instead of silently scanning less.
const SOURCES: &[(&str, &str)] = &[
    ("menus.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/menus.rs"))),
    ("panels.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/panels.rs"))),
    ("dialogs.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/dialogs.rs"))),
    ("diagnostics.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/diagnostics.rs"))),
    ("tour_render.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/tour_render.rs"))),
    ("farm_client.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/farm_client.rs"))),
    ("farm_controller.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/farm_controller.rs"))),
    ("central.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/ui/central.rs"))),
    ("help.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/help.rs"))),
    ("icons.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/icons.rs"))),
    // ⚠⚠**`main.rs` was NOT scanned, and it draws UI text.** The gradient editor's `⊕`/`⊖`
    // affordances, its hint lines and its tooltips all live here, so the one file with the most
    // recently-written glyphs was the one file this check could not see. Adding it is the whole
    // point of the module: a glyph is only safe if something looked for a font that can draw it.
    ("main.rs", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/src/main.rs"))),
];

/// The interface's text itself (design/multilingual.md): most of what the windows draw is here,
/// not in the sources above. Every line but a comment is text, so every line is scanned.
const LANGUAGE_FILES: &[(&str, &str)] =
    &[("i18n/en/fractadyne.ftl", include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../i18n/en/fractadyne.ftl")))];

fn covered() -> BTreeSet<u32> {
    let mut set = BTreeSet::new();
    for (name, bytes) in FONTS {
        let face = ttf_parser::Face::parse(bytes, 0).unwrap_or_else(|e| panic!("{name}: {e}"));
        for ch in 0u32..=0x10FFFF {
            if let Some(c) = char::from_u32(ch) {
                if face.glyph_index(c).is_some() {
                    set.insert(ch);
                }
            }
        }
    }
    set
}

/// Non-ASCII characters on any line holding a string literal. Deliberately crude: it
/// OVER-collects (a character in a trailing comment counts) rather than under-collects.
/// Over-collecting costs one covered glyph in a list; under-collecting is how a tofu ships.
fn used() -> Vec<(u32, &'static str, usize)> {
    let mut out = Vec::new();
    let mut seen = BTreeSet::new();
    let mut scan = |file: &'static str, n: usize, line: &str| {
        for ch in line.chars().filter(|c| !c.is_ascii()) {
            if seen.insert(ch as u32) {
                out.push((ch as u32, file, n + 1));
            }
        }
    };
    for (file, src) in SOURCES {
        for (n, line) in src.lines().enumerate() {
            if !line.trim_start().starts_with("//") && line.contains('"') {
                scan(file, n, line);
            }
        }
    }
    for (file, src) in LANGUAGE_FILES {
        for (n, line) in src.lines().enumerate() {
            if !line.starts_with('#') {
                scan(file, n, line);
            }
        }
    }
    out
}

#[test]
fn every_ui_glyph_has_a_font_that_can_draw_it() {
    let have = covered();
    let want = used();
    assert!(want.len() > 20, "only {} glyphs scanned â€” the scan is broken", want.len());
    let missing: Vec<_> = want.iter().filter(|(cp, _, _)| !have.contains(cp)).collect();
    assert!(
        missing.is_empty(),
        "{} glyph(s) no bundled font can draw â€” each renders as a blank box:\n{}",
        missing.len(),
        missing
            .iter()
            .map(|(cp, f, l)| format!(
                "  U+{cp:04X} {:?} at {f}:{l}",
                char::from_u32(*cp).unwrap_or('?')
            ))
            .collect::<Vec<_>>()
            .join("\n")
    );
}

/// The check above is worthless if it cannot fail, and "nothing missing" looks exactly like
/// "the font scan returned everything". This pins both halves.
#[test]
fn the_coverage_check_can_actually_fail() {
    let have = covered();
    assert!(have.len() > 1000, "font scan produced only {} codepoints", have.len());

    // The four that actually shipped as tofu, plus an unassigned codepoint.
    for cp in [0x270Eu32, 0x2713, 0x2715, 0x1F916, 0x10FFFD] {
        assert!(
            !have.contains(&cp),
            "U+{cp:04X} now reports as covered â€” if a font gained it, give this negative \
             control a different codepoint rather than deleting it"
        );
    }
    for cp in [0x2716u32, 0x2714, 0x0041] {
        assert!(have.contains(&cp), "U+{cp:04X} should be covered");
    }
    // A Lucide icon: without this, dropping the subset from the build would blank every icon
    // in the UI and the test above would still pass.
    let helm = crate::icons::AUTOPILOT.chars().next().unwrap() as u32;
    assert!(have.contains(&helm), "the Lucide subset is missing (U+{helm:04X})");
}

/// Han, kana and the full-width forms: what a Japanese or Chinese interface draws with the system's
/// font for its language (`i18n::fonts`), which no bundled font provides.
fn drawn_by_a_system_font(c: char) -> bool {
    matches!(c as u32, 0x2E80..=0x2FDF | 0x3000..=0x30FF | 0x3100..=0x312F | 0x31F0..=0x31FF | 0x3200..=0x9FFF | 0xF900..=0xFAFF | 0xFE30..=0xFE4F | 0xFF00..=0xFFEF | 0x20000..=0x3134F)
}

/// Every language file shipped beside the English one draws with the fonts its script has: the
/// bundled fonts for every character, except that a Japanese or Chinese file's Han, kana and
/// full-width characters come from the system's font for it. Its own name, though, must be in the
/// bundled names fonts: the language menu shows it in every interface language. Read at test time,
/// so a new file is checked without a change here.
#[test]
fn every_language_file_draws_with_the_fonts_its_script_has() {
    let have = covered();
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../i18n");
    let mut missing = Vec::new();
    let mut files = 0;
    for entry in std::fs::read_dir(&dir).expect("i18n/").flatten() {
        let tag = entry.file_name().to_string_lossy().into_owned();
        let path = entry.path().join("fractadyne.ftl");
        if tag == "en" || !path.is_file() {
            continue;
        }
        files += 1;
        let text = std::fs::read_to_string(&path).expect("UTF-8");
        let script = text.lines().find_map(|l| l.strip_prefix("language-script")).and_then(|v| v.split('=').nth(1)).map(str::trim).unwrap_or("Latn").to_owned();
        let system = matches!(script.as_str(), "Jpan" | "Hans");
        for (n, line) in text.lines().enumerate() {
            if line.starts_with('#') {
                continue;
            }
            let own_name = line.starts_with("language-name");
            for c in line.chars().filter(|c| !c.is_ascii()) {
                if system && !own_name && drawn_by_a_system_font(c) {
                    continue;
                }
                if !have.contains(&(c as u32)) {
                    missing.push(format!("  U+{:04X} {c:?} at i18n/{tag}/fractadyne.ftl:{}", c as u32, n + 1));
                }
            }
        }
    }
    missing.dedup();
    assert!(
        missing.is_empty(),
        "{} character(s) in {files} language file(s) that no font of their script can draw:\n{}",
        missing.len(),
        missing.join("\n")
    );
}
